// 把 TS 核心（命令行 + 本地控制台）打成单文件 ESM：依赖全部内联，运行时只需要 Node（或 Electron 自带的 Node）。
// 桌面端打包时随应用分发；默认配置、提示词、门禁脚本、页面仍从 assets 目录读（WWK_ASSETS 指定）。
import { build } from "esbuild"

await build({
  entryPoints: ["src/cli.ts"],
  outfile: "dist/wwk.mjs",
  bundle: true,
  platform: "node",
  format: "esm",
  target: "node22",
  legalComments: "none",
  banner: {
    // nodemailer 等依赖是 CommonJS，会 require 内置模块；ESM 产物里得补一个真正的 require
    js: [
      "// GENERATED by core/build.mjs from core/src — do not edit.",
      "import { createRequire as __wwkCreateRequire } from \"node:module\";",
      "const require = __wwkCreateRequire(import.meta.url);",
    ].join("\n"),
  },
  logLevel: "warning",
})
